function generate(rand, size) {
  if (size === 'large') return [500 + Math.floor(rand() * 501)];
  // Values next to a power of two are where off-by-one mistakes show up.
  if (rand() < 0.5) {
    const power = 2 ** Math.floor(rand() * 10);
    return [Math.min(1000, Math.max(1, power + Math.floor(rand() * 3) - 1))];
  }
  return [1 + Math.floor(rand() * 1000)];
}
